// Nome da função: preencherMedidasAleatorias
function preencherMedidasAleatorias() {
    // Filtra apenas os campos do tipo "numero"
    const campos = (script && script.camposScript ? script.camposScript : [])
        .filter(campo => campo.tipo === "numero");

    let total = 0;

    campos.forEach(campo => {
        // Busca o elemento input do campo
        const input = document.querySelector("#VR_" + campo.nome)
            ?.querySelector(moduloScript.seletorCampo);

        // Se não encontrou ou está desabilitado, pula este campo
        if (!input || input.disabled) {
            return;
        }

        // Obtém a quantidade de casas decimais
        const casasDecimais = Number.parseInt(campo.casasDecimais, 10) || 0;

        // Filtra referências de normalidade que sejam válidas
        const referencias = (campo.referenciaNormalidade || [])
            .map(ref => ({
                min: utilNum.parsePtBrNumber(ref.valorMin),
                max: utilNum.parsePtBrNumber(ref.valorMax)
            }))
            .filter(ref => Number.isFinite(ref.min) && Number.isFinite(ref.max) && ref.max > ref.min);

        // Define os limites para o valor aleatório
        const valorMin = referencias.length > 0
            ? Math.min(...referencias.map(ref => ref.min))
            : 1;

        const valorMax = referencias.length > 0
            ? Math.max(...referencias.map(ref => ref.max))
            : (casasDecimais > 0 ? 99 : 999);

        // Gera um valor aleatório dentro dos limites
        const valor = (Math.random() * (valorMax - valorMin) + valorMin)
            .toFixed(casasDecimais);

        // Verifica se o AutoNumeric está presente e aplica o valor
        const autoNumericElemento = typeof AutoNumeric !== "undefined"
            ? AutoNumeric.getAutoNumericElement(input)
            : null;

        if (autoNumericElemento) {
            autoNumericElemento.set(valor);
        } else {
            input.value = valor.toString().replace(".", ",");
        }

        // Atualiza o valor padrão do campo
        campo.valorPadrao = input.value;

        // Dispara eventos para sincronização
        moduloScript.executarEvento(input, "input");
        moduloScript.executarEvento(input, "change");

        total++;
    });

    // Atualiza funções auxiliares, se existirem
    if (typeof funcoesScript !== "undefined" && typeof funcoesScript.atualizar === "function") {
        funcoesScript.atualizar();
    }

    if (typeof atualizarImpressaoVisualizador === "function") {
        atualizarImpressaoVisualizador();
    }

    // Exibe mensagem de sucesso
    if (typeof showMsg === "function") {
        showMsg("sucesso", total + " medidas preenchidas aleatoriamente.", true);
    }
}
